    code: 'from math import dist\n\n\ndef center_sum_early(cluster):\n    best_point = cluster[0]\n    best_sum = float("inf")\n\n    for candidate in cluster:\n        total = 0.0\n\n        for point in cluster:\n            total += dist(candidate, point)\n\n            if total >= best_sum:\n                break\n\n        if total < best_sum:\n            best_sum = total\n            best_point = candidate\n\n    return best_point\n\n\nprint(center_sum_early([(0, 0), (5, 0)]))',
